// @FIGURE_CODE_BEGIN
// === ELEMENT SPECS ===
// photograph plane → PlaneGeometry tiles with CanvasTexture (graffiti art)
// tiles → separate PlaneGeometry meshes, per-tile UV offsets, white gaps 0.04
// fine token grid → drawn on CanvasTexture as subtle dark lines
// token dots → CircleGeometry(0.025) meshes inside selected tile (3×3 sub-grid)
// attention lines → LineSegments (orange #ff8800) complete graph among tokens
// selected border → LineLoop (cyan #00c8d8) around selected tile
// caption → addLabel below plane, updates with controls

const GAP = 0.04;
const PLANE_W = 4, PLANE_H = 3;
let currentN = 4;
let currentOffset = false;
let selectedTileIdx = -1;
let tileMeshes = [];
let tileData = [];

// --- Graffiti CanvasTexture ---
function createGraffitiTexture() {
  const cv = document.createElement('canvas');
  cv.width = 512; cv.height = 384;
  const ctx = cv.getContext('2d');

  // Wall background
  ctx.fillStyle = '#b9c6cd';
  ctx.fillRect(0, 0, 512, 384);

  // Dark top strip
  ctx.fillStyle = '#2a2a2a';
  ctx.fillRect(0, 0, 512, 28);

  // Greenery hint at top
  ctx.fillStyle = '#4a7a3a';
  for (let i = 0; i < 20; i++) {
    ctx.fillRect(Math.random()*512, 28, 8+Math.random()*12, 6+Math.random()*8);
  }

  // Pink face (upper center-left)
  ctx.fillStyle = '#f2a3c4';
  ctx.beginPath();
  ctx.ellipse(195, 130, 55, 65, 0, 0, Math.PI*2);
  ctx.fill();
  // Hair
  ctx.fillStyle = '#2a2a2a';
  ctx.beginPath();
  ctx.ellipse(195, 95, 58, 35, 0, Math.PI, 0);
  ctx.fill();
  // Eyes
  ctx.fillStyle = '#333';
  ctx.beginPath(); ctx.arc(180, 125, 7, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(210, 125, 7, 0, Math.PI*2); ctx.fill();
  // Mouth
  ctx.strokeStyle = '#333'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(195, 145, 12, 0.2, Math.PI-0.2); ctx.stroke();

  // Yellow shirt body
  ctx.fillStyle = '#f2c21a';
  ctx.beginPath();
  ctx.moveTo(155, 190);
  ctx.lineTo(235, 190);
  ctx.lineTo(255, 370);
  ctx.lineTo(135, 370);
  ctx.closePath();
  ctx.fill();
  // Bow detail
  ctx.strokeStyle = '#8a6a00'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(185, 210); ctx.lineTo(195, 220); ctx.lineTo(205, 210); ctx.stroke();

  // Red scribbles left
  ctx.strokeStyle = '#d2202f'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(30, 200); ctx.quadraticCurveTo(55, 260, 35, 320); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(55, 210); ctx.quadraticCurveTo(75, 270, 55, 330); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(20, 250); ctx.quadraticCurveTo(40, 280, 25, 340); ctx.stroke();

  // Red scribbles right
  ctx.beginPath(); ctx.moveTo(370, 140); ctx.quadraticCurveTo(410, 200, 390, 290); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(395, 160); ctx.quadraticCurveTo(435, 220, 415, 310); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(350, 180); ctx.quadraticCurveTo(380, 230, 360, 300); ctx.stroke();

  // Additional graffiti marks
  ctx.strokeStyle = '#d2202f'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(290, 90); ctx.lineTo(340, 120); ctx.lineTo(310, 150); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(420, 80); ctx.lineTo(460, 110); ctx.stroke();

  // Purple dots
  ctx.fillStyle = '#6a3a8a';
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.arc(60+Math.random()*400, 60+Math.random()*300, 3+Math.random()*4, 0, Math.PI*2);
    ctx.fill();
  }

  // Fine token grid (subtle)
  ctx.strokeStyle = 'rgba(34,34,34,0.25)';
  ctx.lineWidth = 0.8;
  const gx = 512/32, gy = 384/24;
  for (let i = 0; i <= 32; i++) {
    ctx.beginPath(); ctx.moveTo(i*gx, 0); ctx.lineTo(i*gx, 384); ctx.stroke();
  }
  for (let j = 0; j <= 24; j++) {
    ctx.beginPath(); ctx.moveTo(0, j*gy); ctx.lineTo(512, j*gy); ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(cv);
  tex.needsUpdate = true;
  return tex;
}

const graffitiTex = createGraffitiTexture();

// --- Tile computation ---
function computeTiles(N, offset) {
  const tiles = [];
  const tw = 1.0/N, th = 1.0/N;
  const sx = offset ? tw/2 : 0;
  const sy = offset ? th/2 : 0;
  for (let j = 0; j <= N; j++) {
    for (let i = 0; i <= N; i++) {
      const x0 = i*tw - sx, y0 = j*th - sy;
      const x1 = x0+tw, y1 = y0+th;
      const cx0 = Math.max(0, x0), cy0 = Math.max(0, y0);
      const cx1 = Math.min(1, x1), cy1 = Math.min(1, y1);
      if (cx1-cx0 < 0.001 || cy1-cy0 < 0.001) continue;
      tiles.push({ u0:cx0, v0:cy0, u1:cx1, v1:cy1 });
    }
  }
  return tiles;
}

// --- Tile group ---
const tileGroup = new THREE.Group();
scene.add(tileGroup);

// --- Selection visuals group ---
const selGroup = new THREE.Group();
scene.add(selGroup);

function rebuildTiles() {
  // Clear old
  while (tileGroup.children.length) {
    const c = tileGroup.children[0];
    tileGroup.remove(c);
    c.geometry?.dispose();
    c.material?.dispose();
  }
  tileMeshes = [];
  tileData = computeTiles(currentN, currentOffset);

  tileData.forEach((tile, idx) => {
    const worldW = (tile.u1-tile.u0)*PLANE_W;
    const worldH = (tile.v1-tile.v0)*PLANE_H;
    const mw = Math.max(0.01, worldW - GAP);
    const mh = Math.max(0.01, worldH - GAP);

    const geo = new THREE.PlaneGeometry(mw, mh);
    const uv = geo.attributes.uv;
    for (let i = 0; i < uv.count; i++) {
      const u = uv.getX(i), v = uv.getY(i);
      uv.setXY(i, tile.u0 + u*(tile.u1-tile.u0), tile.v0 + v*(tile.v1-tile.v0));
    }
    uv.needsUpdate = true;

    const mat = new THREE.MeshBasicMaterial({ map: graffitiTex, side: THREE.DoubleSide });
    const mesh = new THREE.Mesh(geo, mat);
    const cx = ((tile.u0+tile.u1)/2)*PLANE_W - PLANE_W/2;
    const cy = ((tile.v0+tile.v1)/2)*PLANE_H - PLANE_H/2;
    mesh.position.set(cx, cy, 0);
    mesh.userData.tileIdx = idx;
    tileGroup.add(mesh);
    tileMeshes.push(mesh);
  });

  clearSelection();
  updateCaption();
}

// --- Selection ---
function clearSelection() {
  while (selGroup.children.length) {
    const c = selGroup.children[0];
    selGroup.remove(c);
    c.geometry?.dispose();
    c.material?.dispose();
  }
  selectedTileIdx = -1;
  // Restore tile opacity
  tileMeshes.forEach(m => { m.material.opacity = 1; m.material.transparent = false; });
}

function selectTile(idx) {
  clearSelection();
  if (idx < 0 || idx >= tileData.length) return;
  selectedTileIdx = idx;
  const tile = tileData[idx];

  // Dim other tiles
  tileMeshes.forEach((m, i) => {
    if (i !== idx) {
      m.material.transparent = true;
      m.material.opacity = 0.35;
    }
  });

  // Cyan border
  const worldW = (tile.u1-tile.u0)*PLANE_W;
  const worldH = (tile.v1-tile.v0)*PLANE_H;
  const cx = ((tile.u0+tile.u1)/2)*PLANE_W - PLANE_W/2;
  const cy = ((tile.v0+tile.v1)/2)*PLANE_H - PLANE_H/2;
  const hw = worldW/2, hh = worldH/2;
  const borderPts = [
    new THREE.Vector3(cx-hw, cy-hh, 0.01),
    new THREE.Vector3(cx+hw, cy-hh, 0.01),
    new THREE.Vector3(cx+hw, cy+hh, 0.01),
    new THREE.Vector3(cx-hw, cy+hh, 0.01),
  ];
  const borderGeo = new THREE.BufferGeometry().setFromPoints(borderPts);
  const borderMat = new THREE.LineBasicMaterial({ color: 0x00c8d8, linewidth: 2 });
  const border = new THREE.LineLoop(borderGeo, borderMat);
  selGroup.add(border);

  // Token dots (3×3 sub-grid inside tile)
  const tokensPerSide = 3;
  const tokenPositions = [];
  const inset = 0.15; // fraction of tile to inset tokens
  const tw2 = worldW*(1-2*inset), th2 = worldH*(1-2*inset);
  const tx0 = cx - tw2/2, ty0 = cy - th2/2;
  for (let r = 0; r < tokensPerSide; r++) {
    for (let c2 = 0; c2 < tokensPerSide; c2++) {
      const px = tx0 + (c2/(tokensPerSide-1))*tw2;
      const py = ty0 + (r/(tokensPerSide-1))*th2;
      tokenPositions.push(new THREE.Vector3(px, py, 0.02));
      const dotGeo = new THREE.CircleGeometry(0.03, 16);
      const dotMat = new THREE.MeshBasicMaterial({ color: 0x222222, side: THREE.DoubleSide });
      const dot = new THREE.Mesh(dotGeo, dotMat);
      dot.position.set(px, py, 0.02);
      selGroup.add(dot);
    }
  }

  // Attention lines (complete graph)
  const linePts = [];
  for (let a = 0; a < tokenPositions.length; a++) {
    for (let b = a+1; b < tokenPositions.length; b++) {
      linePts.push(tokenPositions[a].clone(), tokenPositions[b].clone());
    }
  }
  const lineGeo = new THREE.BufferGeometry().setFromPoints(linePts);
  const lineMat = new THREE.LineBasicMaterial({ color: 0xff8800, transparent: true, opacity: 0.7 });
  const lines = new THREE.LineSegments(lineGeo, lineMat);
  lines.position.z = 0.015;
  selGroup.add(lines);
}

// --- Click handling ---
const _ray = new THREE.Raycaster();
const _ptr = new THREE.Vector2();
canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  _ptr.x = ((e.clientX-rect.left)/rect.width)*2-1;
  _ptr.y = -((e.clientY-rect.top)/rect.height)*2+1;
  _ray.setFromCamera(_ptr, camera);
  const hits = _ray.intersectObjects(tileMeshes, false);
  if (hits.length > 0) {
    const idx = hits[0].object.userData.tileIdx;
    if (idx === selectedTileIdx) clearSelection();
    else selectTile(idx);
  } else {
    clearSelection();
  }
});

// --- Caption ---
let captionLabel = null;
function updateCaption() {
  const n = currentN;
  let text;
  if (n === 1) text = '1×1 window';
  else if (currentOffset) text = `${n}×${n} offset windows`;
  else text = `${n}×${n} windows`;
  if (captionLabel) {
    captionLabel.div.innerHTML = text;
  } else {
    captionLabel = addLabel(text, new THREE.Vector3(0, -2.1, 0), { fontSize: '15px', bold: true });
  }
}

// --- UI wiring ---
const sliderEl = document.getElementById('windowSize');
const sliderValEl = document.getElementById('windowSizeVal');
const btnReg = document.getElementById('btnRegular');
const btnOff = document.getElementById('btnOffset');

sliderEl.addEventListener('input', () => {
  currentN = parseInt(sliderEl.value);
  sliderValEl.textContent = currentN;
  rebuildTiles();
});

btnReg.addEventListener('click', () => {
  currentOffset = false;
  btnReg.classList.add('active');
  btnOff.classList.remove('active');
  rebuildTiles();
});

btnOff.addEventListener('click', () => {
  currentOffset = true;
  btnOff.classList.add('active');
  btnReg.classList.remove('active');
  rebuildTiles();
});

// --- Demo steps ---
const steps = [
  { n: 4, offset: false, title: '4×4 regular windows (panel b)' },
  { n: 4, offset: true, title: '4×4 offset windows (panel c)' },
  { n: 2, offset: false, title: '2×2 windows (panel d)' },
  { n: 1, offset: false, title: '1×1 global window (panel f)' },
];

function goToStep(i) {
  const s = steps[i];
  currentN = s.n;
  currentOffset = s.offset;
  sliderEl.value = currentN;
  sliderValEl.textContent = currentN;
  if (currentOffset) { btnOff.classList.add('active'); btnReg.classList.remove('active'); }
  else { btnReg.classList.add('active'); btnOff.classList.remove('active'); }
  rebuildTiles();
  showPopup(s.title, steps[i].narration || '');
}

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
document.getElementById('step3').addEventListener('click', () => goToStep(3));

// --- Build initial scene ---
rebuildTiles();

// --- Camera ---
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, heightFraction: 0.7 });
// @FIGURE_CODE_END

